vec3 hsv2rgb(float h, float s, float v) {
    float c = v * s;
    float x = c * (1.0 - abs(mod(h / 60.0, 2.0) - 1.0));
    float m = v - c;
    vec3 rgb;

    if (h < 60.0) rgb = vec3(c, x, 0.0);
    else if (h < 120.0) rgb = vec3(x, c, 0.0);
    else if (h < 180.0) rgb = vec3(0.0, c, x);
    else if (h < 240.0) rgb = vec3(0.0, x, c);
    else if (h < 300.0) rgb = vec3(x, 0.0, c);
    else rgb = vec3(c, 0.0, x);

    return (rgb + vec3(m)) * 255.0;
}
vec2 corrigirCoord(vec2 fragCoord, float zoom, vec2 offset) {
    return (fragCoord - iResolution.xy * 0.5) * (4.0 / (zoom * iResolution.x)) + offset;
}
int mandelbrot(vec2 c, int maxIter) {
    vec2 z = vec2(0.0, 0.0);
    int n;
    for (n = 0; n < maxIter; n++) {
        z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
        if (dot(z, z) > 4.0) break;
    }
    return n;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float zoom = pow(pow(2.0, iTime / 0.117), 0.0546);;
    vec2 offset = vec2(-0.743643887037151, 0.13182590420533);
    vec2 c = corrigirCoord(fragCoord, zoom, offset);
    int maxIter = 2048;
    int iter = mandelbrot(c, maxIter);
    float hue = float(mod(float(iter),360.0));
    float sat = float(min(1.0,3600.0*(float(maxIter)-float(iter))/(360.0*float(maxIter))));
    vec3 color = hsv2rgb(hue, sat, 1.0);
    if (iter == maxIter) {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
    } else {
        fragColor = vec4(color, 1.0);
    }
}
